const languageIndexes: Record<Language, number> = { EN: 0, BM: 1, CN: 2 };
export const translationCatalog = messages;
export const languageLocales: Record<Language, string> = { EN: 'en-MY', BM: 'ms-MY', CN: 'zh-CN' };
const STORAGE_KEY = 'futurenow.language.v1';

type I18nValue = { language: Language; setLanguage: (value: Language) => void; t: (messageId: string, values?: Record<string, string | number>) => string };
const I18nContext = createContext<I18nValue | null>(null);

export function translateMessage(messageId: string, language: Language, values: Record<string, string | number> = {}) {
  const localized = messages[messageId]?.[languageIndexes[language]];
  const english = messages[messageId]?.[0] ?? messageId;
  const message = localized?.trim() ? localized : english;
  return message.replace(/\{(\w+)\}/g, (_, name: string) => String(values[name] ?? `{${name}}`));
}

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<Language>(() => {
    try {
      const stored = window.localStorage.getItem(STORAGE_KEY);
      return stored === 'BM' || stored === 'CN' ? stored : 'EN';
    } catch {
      return 'EN';
    }
  });
  useEffect(() => {
    document.documentElement.lang = language === 'BM' ? 'ms' : language === 'CN' ? 'zh-CN' : 'en';
    try { window.localStorage.setItem(STORAGE_KEY, language); } catch { /* Preference remains available for this session. */ }
  }, [language]);
  const value = useMemo<I18nValue>(() => ({
    language,
    setLanguage: setLanguageState,
    t: (messageId, values = {}) => translateMessage(messageId, language, values),
  }), [language]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useTranslation() {
  const value = useContext(I18nContext);
  if (!value) throw new Error('useTranslation must be used inside LanguageProvider');
  return value;
}

export function LanguageSwitcher() {
  const { language, setLanguage, t } = useTranslation();
  return <div className="language-switcher" role="group" aria-label={t('Select a language')} data-testid="language-switcher">
    {(['EN', 'BM', 'CN'] as const).map((option) => (
      <button
        key={option}
        type="button"
        lang={option === 'BM' ? 'ms' : option === 'CN' ? 'zh-CN' : 'en'}
        aria-label={t(option === 'EN' ? 'English' : option === 'BM' ? 'Bahasa Melayu' : 'Simplified Chinese')}
        aria-pressed={language === option}
        className={language === option ? 'language-active' : ''}
        onClick={() => setLanguage(option)}
        data-testid={`button-language-${option}`}
      >{option}</button>
    ))}
  </div>;
}
